here = os.path.dirname(os.path.abspath(__file__))
def esc(s): return s.replace("\\", "\\\\").replace('"', '\\"')
for i, lang in enumerate(LANGS):
    d = os.path.join(here, "Resources", lang + ".lproj"); os.makedirs(d, exist_ok=True)
    with open(os.path.join(d, "Localizable.strings"), "w", encoding="utf-8") as f:
        for k, v in T.items():
            assert len(v) == len(LANGS), k
            f.write('"%s" = "%s";\n' % (esc(k), esc(v[i])))
os.makedirs(os.path.join(here, "Resources", "en.lproj"), exist_ok=True)
open(os.path.join(here, "Resources", "en.lproj", "Localizable.strings"), "w").write("/* English: the keys are the English texts. */\n")
print(len(T), "strings,", len(LANGS) + 1, "languages")
